def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        freq = defaultdict(set)
        hits = defaultdict(int)

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs))
            if key not in cache:
                cache[key] = func(*args, **kwargs)
                freq[key].add(len(cache))
            else:
                hits[key] += 1
                freq[key].remove(len(cache))
                freq[key].add(len(cache))
            if len(cache) > maxsize:
                # least frequently used
                for key, _ in freq.items():
                    if len(freq[key]) == 1:
                        del cache[key]
                        break
            return cache[key]
        return wrapper
    return decorator

