def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    import subprocess

    if isinstance(commands, str):
        commands = [commands]

    if verbose:
        print("Running command:", " ".join(commands))

    try:
        process = subprocess.Popen(commands, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        output, error = process.communicate(args, timeout=None)
        if process.returncode != 0:
            raise subprocess.CalledProcessError(process.returncode, commands)
        if not hide_stderr:
            print(error.decode("utf-8"))
        return output.decode("utf-8")
    except subprocess.CalledProcessError as e:
        print("Command '{}' returned non-zero exit status {}. Output: {}".format(commands, e.returncode, e.output))
        raise e
    except subprocess.TimeoutExpired as e:
        print("Command '{}' timed out after {} seconds.".format(commands, e.timeout))
