    if not tentative:
        iface_provided_by = iface.providedBy(candidate)
        if not iface_provided_by:
            raise zope.interface.Invalid("Candidate does not provide the interface")

    for method in iface.names():
        if not hasattr(candidate, method):
            raise zope.interface.Invalid("Candidate does not define method {}".format(method))

        method_signature = iface.getMethodSignature(method)
        candidate_method = getattr(candidate, method)
        if not method_signature.isCompatibleWith(candidate_method):
            raise zope.interface.Invalid("Method {} has an incompatible signature".format(method))

    for attribute in iface.names():
        if not hasattr(candidate, attribute):
            raise zope.interface.Invalid("Candidate does not define attribute {}".format(attribute))

    return True

